import json
import os
import random
import ctypes
import sys

# When frozen (PyInstaller onefile), __file__ points to a temp dir -> use the EXE folder instead
if getattr(sys, "frozen", False):
    APP_DIR = os.path.dirname(sys.executable)
else:
    APP_DIR = os.path.dirname(os.path.abspath(__file__))

CONFIG_FILE = os.path.join(APP_DIR, "config.json")

# Optional build-time default (build_config.py is gitignored, generated by build.ps1)
try:
    from build_config import DEFAULT_RELAY
except ImportError:
    DEFAULT_RELAY = "ws://localhost:8765"

def ensure_desktop_access():
    """Ensures thread has access to active Windows desktop station."""
    if sys.platform == "win32":
        try:
            user32 = ctypes.windll.user32
            hdesk = user32.OpenInputDesktop(0, False, 0x01FF) # GENERIC_ALL
            if hdesk:
                user32.SetThreadDesktop(hdesk)
        except Exception:
            pass

def generate_id():
    """Generates a random 6-digit ID like 384 192."""
    return f"{random.randint(100, 999)} {random.randint(100, 999)}"

def generate_password():
    """Generates a random 6-character alphanumeric password."""
    chars = "abcdefghjkmnpqrstuvwxyz23456789"
    return "".join(random.choices(chars, k=6))

def load_config():
    default_config = {
        "relay_server": DEFAULT_RELAY,
        "my_id": generate_id(),
        "my_password": generate_password(),
        "quality": 55,
        "max_fps": 30,
        "scale": 0.75
    }
    if os.path.exists(CONFIG_FILE):
        try:
            with open(CONFIG_FILE, "r", encoding="utf-8") as f:
                saved = json.load(f)
                default_config.update(saved)
            # Stale localhost entry but a real server is baked in -> use it
            if "localhost" in default_config.get("relay_server", "") and "localhost" not in DEFAULT_RELAY:
                default_config["relay_server"] = DEFAULT_RELAY
                save_config(default_config)
        except Exception:
            pass
    else:
        save_config(default_config)
    return default_config

def save_config(cfg):
    try:
        with open(CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(cfg, f, indent=2)
    except Exception:
        pass
